const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '单位换算表：km/h 换算为 m/s' },
      { kind: 'text', payload: '原值' },
      { kind: 'text', payload: '换算算式（除以 3.6）' },
      { kind: 'text', payload: '结果（三位有效数字）' },
      { kind: 'text', payload: '54 km/h' },
      { kind: 'text', payload: '54 ÷ 3.6' },
      { kind: 'text', payload: '15.0 m/s' },
      { kind: 'text', payload: '依据：m/s = (km/h) ÷ 3.6' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var m = Math.max(24, Math.round(W * 0.06));
    var tableX = m;
    var tableW = W - 2 * m;
    var tableY = 100;
    var headerH = 52;
    var rowH = 64;
    var c0 = tableW * 0.26;
    var c1 = tableW * 0.36;
    var c2 = tableW - c0 - c1;
    var bottom = tableY + headerH + rowH;
    function rect(x, y, w, h) {
      return [['M', x, y], ['L', x + w, y], ['L', x + w, y + h], ['L', x, y + h], ['Z']];
    }
    var grid = [];
    var ys = [tableY, tableY + headerH, bottom];
    for (var i = 0; i < ys.length; i++) {
      grid.push(['M', tableX, ys[i]]);
      grid.push(['L', tableX + tableW, ys[i]]);
    }
    var xs = [tableX, tableX + c0, tableX + c0 + c1, tableX + tableW];
    for (var j = 0; j < xs.length; j++) {
      grid.push(['M', xs[j], tableY]);
      grid.push(['L', xs[j], bottom]);
    }
    var cx0 = tableX + c0 / 2;
    var cx1 = tableX + c0 + c1 / 2;
    var cx2 = tableX + c0 + c1 + c2 / 2;
    var hy = tableY + headerH / 2;
    var dy = tableY + headerH + rowH / 2;
    var ink = '#1E293B';
    var line = '#334155';
    return {
      schemaVersion: 1,
      sceneId: 'unit-conversion-table',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'tableBg', commands: rect(tableX, tableY, tableW, headerH + rowH) },
        { id: 'headerBg', commands: rect(tableX, tableY, tableW, headerH) },
        { id: 'grid', commands: grid }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'tableBg', fill: '#FFFFFF' },
          { type: 'path', pathId: 'headerBg', fill: '#E2E8F0', stroke: { width: 2 } },
          { type: 'path', pathId: 'grid', fill: line, stroke: { width: 2, cap: 'butt', join: 'miter' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: W / 2, y: 54 }, hAlign: 'center', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx0, y: hy }, hAlign: 'center', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: cx1, y: hy }, hAlign: 'center', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: cx2, y: hy }, hAlign: 'center', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: cx0, y: dy }, hAlign: 'center', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: cx1, y: dy }, hAlign: 'center', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: cx2, y: dy }, hAlign: 'center', vAlign: 'middle', color: ink },
          { type: 'label', contentId: metrics[7].contentId, anchor: { x: W / 2, y: bottom + 40 }, hAlign: 'center', vAlign: 'middle', color: ink }
        ]
      }
    };
  }
};
